try
    x = prod (G, 'crud') ; %#ok<*NASGU>
    ok = false ;
catch expected_error
    fprintf ('    expected error: %s\n', expected_error.message) ;
end
assert (ok) ;

try
    x = min (G, [ ], 'crud') ;
    ok = false ;
catch expected_error
    fprintf ('    expected error: %s\n', expected_error.message) ;
end
assert (ok) ;

try
    x = max (G, [ ], 'crud') ;
    ok = false ;
catch expected_error
    fprintf ('    expected error: %s\n', expected_error.message) ;
end
assert (ok) ;

try
    x = min (G, [ ], 1, G) ;
    ok = false ;
catch expected_error
    fprintf ('    expected error: %s\n', expected_error.message) ;
end
assert (ok) ;

try
    x = max (G, [ ], 1, G) ;
    ok = false ;
catch expected_error
    fprintf ('    expected error: %s\n', expected_error.message) ;
end
assert (ok) ;

try
    x = sum (G, 'crud') ;
