    ok = false ;
catch expected_error
    fprintf ('    expected error: %s\n', expected_error.message) ;
end
assert (ok) ;

try
    x = bandwidth (G, 'crud') ;
    ok = false ;
catch expected_error
    fprintf ('    expected error: %s\n', expected_error.message) ;
end
